using Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace Infrastructure.Data.Configurations;

public static partial class ReceptionistModelConfiguration
{
    private static void ConfigureSetupGuide(ModelBuilder model, string collation)
    {
        var guide = model.Entity<ReceptionistSetupGuideRevision>();
        guide.ToTable("ReceptionistSetupGuideRevisions", table =>
            table.HasCheckConstraint("CK_ReceptionistSetupGuide_Version", "[Version] >= 1"));
        guide.HasKey(x => x.Version);
        guide.Property(x => x.Version).ValueGeneratedNever();
        guide.HasIndex(x => x.Revision).IsUnique();
        guide.Property(x => x.BusinessGuideJson).HasMaxLength(131072).UseCollation(collation).IsRequired();
        guide.Property(x => x.FounderGuideJson).HasMaxLength(131072).UseCollation(collation).IsRequired();
        guide.Property(x => x.CreatedByActorId).HasMaxLength(450).UseCollation(collation).IsRequired();
        // Immutable V1 is migration seed only. Reads never substitute these defaults for stored content.
        // All later edits append a revision through the canonical Founder publication operation.
        guide.HasData(new ReceptionistSetupGuideRevision
        {
            Version = 1,
            Revision = new Guid("3d5b7f2b-2ce8-4c95-8eac-d94ef2b5c6c3"),
            CreatedUtc = new DateTime(2026, 11, 7, 15, 0, 0, DateTimeKind.Utc),
            CreatedByActorId = "system:initial-receptionist-setup-guide",
            BusinessGuideJson = InitialBusinessGuide,
            FounderGuideJson = InitialFounderGuide
        });
    }

